{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Ziprasidone, a highly transferable analogue, has absolute oral bioavailability of about 60% in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "MMV367, with a very high assay-transfer score, was estimated to have 90% human oral bioavailability, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Vilazodone has an absolute oral bioavailability of 72% in humans with food, clearly above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Apixaban shows moderate-to-good oral bioavailability of 49% in humans at clinical doses, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Indomethacin in adults has approximately 98% oral bioavailability, supporting high F; the low infant-specific values are not transferable to the adult query context.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Asciminib has an absolute oral bioavailability of approximately 73% in humans, well above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Delpazolid/LCB01-0371 has an absolute oral bioavailability of 99.75% in healthy volunteers, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Urapidil has an absolute oral bioavailability of 78% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Piperaquine has a modeled oral bioavailability of 0.77 in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Ivosidenib has an absolute oral bioavailability of 57.2% under fasted conditions in healthy subjects, directly matching the fasted query condition and exceeding the threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability values well above 20%, ranging from 49% to ~100%, including a fasted-state measurement. The query's azole antifungal structure is consistent with high oral absorption, so F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself was provided; the prediction relies on high-transfer analogues.",
    "Some supporting analogue values were obtained under fed conditions, whereas the query condition is fasted; however, fasted ivosidenib and the generally high F of the azole class mitigate this gap.",
    "No high-transfer analogue with low oral bioavailability was retrieved."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

